/** 統一的訂閱封裝，回傳取消訂閱函式 */
function subscribe(channel, cb) {
	const listener = (_e, payload) => cb(payload);
	electron.ipcRenderer.on(channel, listener);
	return () => {
		electron.ipcRenderer.off(channel, listener);
	};
}
